def import_short_and_cq():
    with app.app_context():
        class_obj = ClassLevel.query.filter(ClassLevel.name.like('%৯ম-১০ম%')).first()
        subject_obj = Subject.query.filter_by(class_id=class_obj.id, name="বাংলা সাহিত্য").first()
        chapter_obj = Chapter.query.filter(Chapter.subject_id == subject_obj.id, Chapter.title.like('%বই পড়া%')).first()
        
        print(f"Target: Class ID {class_obj.id}, Subject ID {subject_obj.id}, Chapter ID {chapter_obj.id}")
        
        # Find Topic for Short / CQ
        cq_topic = None
        for t in chapter_obj.topics:
            if "CQ" in t.title or "সৃজনশীল" in t.title:
                cq_topic = t
                break
        if not cq_topic and chapter_obj.topics:
            cq_topic = chapter_obj.topics[0]
            
        topic_id = cq_topic.id if cq_topic else None
        print(f"Topic: {cq_topic.title if cq_topic else 'None'} (ID {topic_id})")
        
        # 1. Insert 45 Short Questions
        short_count = 0
        for item in short_questions_data:
            q = Question(
                class_id=class_obj.id,
                subject_id=subject_obj.id,
                chapter_id=chapter_obj.id,
                topic_id=topic_id,
                question_type='short',
                difficulty='medium',
                marks=2.0,
                short_question=item['q'],
                short_answer=item['ans']
            )
            db.session.add(q)
            short_count += 1
            
        # 2. Insert 13 Creative Questions (CQ)
        cq_count = 0
        for item in cq_questions_data:
            q = Question(
                class_id=class_obj.id,
                subject_id=subject_obj.id,
                chapter_id=chapter_obj.id,
                topic_id=topic_id,
                question_type='cq',
                difficulty='medium',
                marks=10.0,
                cq_stem=item['stem'],
                cq_sub_ka=item['ka'],
                cq_sub_kha=item['kha'],
                cq_sub_ga=item['ga'],
                cq_sub_gha=item['gha'],
                cq_solution=item['solution']
            )
            db.session.add(q)
            cq_count += 1
            
        db.session.commit()
        print(f"Successfully added {short_count} Short Questions and {cq_count} Creative Questions (CQ)!")

if __name__ == '__main__':
    import_short_and_cq()
